<script setup>
import { ref,computed,watch } from 'vue';import { useRoute } from 'vue-router';import { SlidersHorizontal } from 'lucide-vue-next';import { api } from '../lib/api';import SearchForm from '../components/SearchForm.vue';import RoomCard from '../components/RoomCard.vue';import StatePanel from '../components/StatePanel.vue';
const route=useRoute(),rooms=ref([]),loading=ref(true),error=ref(''),sort=ref('price'),filter=ref(''),meta=ref(null);
const searching=computed(()=>Boolean(route.query.check_in&&route.query.check_out));const types=computed(()=>[...new Set(rooms.value.map(r=>r.type_name))]);const shown=computed(()=>{const r=rooms.value.filter(r=>!filter.value||r.type_name===filter.value);return sort.value==='price-desc'?r.sort((a,b)=>Number(b.price_per_night)-Number(a.price_per_night)):r.sort((a,b)=>Number(a.price_per_night)-Number(b.price_per_night));});
let seq=0;async function load(){const n=++seq;loading.value=true;error.value='';try{const q=new URLSearchParams();for(const key of ['check_in','check_out','adults','children','room_type_id'])if(route.query[key])q.set(key,route.query[key]);if(searching.value)q.set('limit','100');const result=await api(searching.value?'/rooms/availability?'+q:'/room-types');if(n===seq){rooms.value=result.data;meta.value=result.meta;filter.value='';}}catch(e){if(n===seq)error.value=e.message;}finally{if(n===seq)loading.value=false;}}watch(()=>route.fullPath,load,{immediate:true});
</script>
<template><section class="page-intro"><div class="container"><p class="eyebrow">FIND YOUR PERFECT STAY</p><h1>ห้องพักของเรา</h1><p>เลือกพื้นที่พักผ่อนที่เหมาะกับคุณและคนสำคัญ</p></div></section><div class="container listing-search"><SearchForm :key="route.fullPath" :initial="route.query"/></div><section class="container section compact"><div class="listing-toolbar"><div><h3>{{ searching?'ห้องว่างสำหรับวันของคุณ':'ประเภทห้องพักทั้งหมด' }}</h3><span class="muted">{{ shown.length }} รายการ<span v-if="meta"> · {{ meta.nights }} คืน</span></span></div><div class="filters"><SlidersHorizontal :size="18"/><label class="sr-only" for="type-filter">ประเภทห้อง</label><select id="type-filter" v-model="filter"><option value="">ทุกประเภทห้อง</option><option v-for="type in types" :key="type">{{ type }}</option></select><label class="sr-only" for="sort-rooms">เรียงลำดับ</label><select id="sort-rooms" v-model="sort"><option value="price">ราคา: ต่ำไปสูง</option><option value="price-desc">ราคา: สูงไปต่ำ</option></select></div></div><StatePanel :loading="loading" :error="error" :empty="!loading&&!error&&!shown.length" @retry="load"/><div v-if="!loading&&!error" class="room-grid"><RoomCard v-for="(room,index) in shown" :key="room.room_id||room.room_type_id" :room="room" :index="index" :query="route.query"/></div><p v-if="searching&&shown.length" class="subtle-note">ราคาที่แสดงเป็นราคาต่อคืน · ห้องจะถูกตรวจสอบอีกครั้งเมื่อยืนยันการจอง</p></section></template>
